// Clean empty/placeholder tokens
for (const k of Object.keys(KW)) {
  KW[k] = KW[k].filter(w => w && w.trim() && !/^x+$/.test(w.trim())).map(w => w.toLowerCase());
}

function scoreText(t) {
  const scores = {};
  for (const [label, words] of Object.entries(KW)) {
    let sc = 0;
    for (const w of words) {
      if (w.length < 3) continue;
      // word boundary-ish
      const idx = t.indexOf(w);
      if (idx >= 0) {
        sc += w.length >= 8 ? 3 : (w.length >= 5 ? 2 : 1);
        // count multiple? once is enough per word
      }
    }
    scores[label] = sc;
  }
  return scores;
}

