function classify(q) {
  const t = q.toLowerCase();

  // Apply first matching high-precision rule with priority order
  // But collect all matches and pick best
  const ruleHits = [];
  for (const [re, label] of RULES) {
    if (re.test(t)) ruleHits.push(label);
  }

  const scores = scoreText(t);
  // boost from rules
  for (const lab of ruleHits) scores[lab] = (scores[lab] || 0) + 10;

  // Priority tiebreak for strong exclusive signals
  if (/\b(nfl|nba|mlb|super ?bowl|world series|wwe|nascar|scudetto|curling olympic|nfc|timberwolves|ravens)\b/i.test(t))
    return 'Sports';
  if (/\b(greenday|beatles|lyrics|who sings|song\b|album|metal band|simpsons|jetsons|survivor|pop star)\b/i.test(t))
    return 'Entertainment & Music';
  if (/\b(spyware|deskpan|flashplayer|firefox browser|cookies on your browser|pen drive|dll\b)\b/i.test(t))
    return 'Computers & Internet';
  if (/\b(municipal bond|corporate bond|coupon rate|tax bracket|e-currency|call and put option|walmart (employee|associate).*w2|8% interest)\b/i.test(t))
    return 'Business & Finance';
  if (/\b(president of|secretary of state|vote for bill clinton|cafta|house of representatives)\b/i.test(t))
    return 'Politics & Government';

  let best = 'Society & Culture';
  let bestSc = -1;
  for (const [k,v] of Object.entries(scores)) {
    if (v > bestSc) { bestSc = v; best = k; }
  }
  if (bestSc <= 0) {
    // secondary heuristics
    if (/\b(how (do|does|can|to)|what (is|are|was)|who (is|was|are)|where (can|do|is)|why (do|does|is|did))\b/i.test(t) && t.length < 60)
      return 'Education & Reference';
    if (/\b(feel|think|should i|help me|please)\b/i.test(t))
      return 'Society & Culture';
    return 'Education & Reference';
  }
  return best;
}

const labels = ['Society & Culture','Health','Education & Reference','Sports','Family & Relationships','Computers & Internet','Science & Mathematics','Business & Finance','Entertainment & Music','Politics & Government'];
const counts = {};
for (const l of labels) counts[l] = 0;

const results = instances.map((text, i) => {
  const label = classify(text);
  counts[label]++;
  return { i, label, text: text.slice(0, 100) };
});

const least = Math.min(...Object.values(counts));
const leastLabels = labels.filter(l => counts[l] === least);
const sum = Object.values(counts).reduce((a,b)=>a+b,0);

// sample 20 stratified
const samples = [];
for (const l of labels) {
  const hit = results.find(r => r.label === l);
  if (hit) samples.push(hit);
}

return JSON.stringify({ n: instances.length, counts, least, leastLabels, sum, samples, 
  // show distribution of first 50 for manual spot check
  first50: results.slice(0, 50)
}, null, 0);

