const labels = ['Society & Culture','Health','Education & Reference','Sports','Family & Relationships','Computers & Internet','Science & Mathematics','Business & Finance','Entertainment & Music','Politics & Government'];
const counts = {};
for (const l of labels) counts[l] = 0;
const results = instances.map((text, i) => {
  const label = classify(text);
  counts[label]++;
  return { i, label, text };
});
const least = Math.min(...Object.values(counts));
const leastLabels = labels.filter(l => counts[l] === least);
const sum = Object.values(counts).reduce((a,b)=>a+b,0);

const first40 = results.slice(0,40).map(r=>({i:r.i,l:r.label,t:r.text.slice(0,75)}));
const sci = results.filter(r=>r.label==='Science & Mathematics').map(r=>({i:r.i,t:r.text.slice(0,100)}));
const samples = [];
for (const l of labels) {
  const hit = results.find(r => r.label === l);
  if (hit) samples.push({label:l, i:hit.i, t:hit.text.slice(0,100)});
}
// spot check random 20
const spot = [50,100,150,200,300,400,500,600,700,800,900,1000,1100,1200,1300,1400,1500,1600,1650,1670].map(i => results[i] && ({i,l:results[i].label,t:results[i].text.slice(0,90)}));

return JSON.stringify({n:instances.length,counts,least,leastLabels,sum,first40,sci,samples,spot},null,0);

