function has(t, words, prefixes=[]) {
  for (const w of words) {
    const re = new RegExp(String.raw`(?:^|[^a-z0-9])${w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}(?:[^a-z0-9]|$)`);
    if (re.test(t)) return true;
  }
  for (const p of prefixes) {
    const re = new RegExp(String.raw`(?:^|[^a-z0-9])${p.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}[a-z]*`);
    if (re.test(t)) return true;
  }
  return false;
}

